        kind: String(kind || ""),
        count: Math.max(1, Number(count || 1)),
        anchor: String(anchor || "target"),
      });
    },
    consumeCharge(entityId, amount = 1) {
      out.chargesToConsume.push({
        source: procNodeId,
        entityId: Number(entityId || 0),
        amount: Math.max(1, Number(amount || 1)),
