export function evaluateProcNode(world, nodeId, ctx, sourceStats = {}, targetStats = {}, out = createProcAccumulator()) {
  const gates = gatherDirectChildrenWith(world, nodeId, ActivationGate);
  for (let i = 0; i < gates.length; i++) {
